const location = query.location;

if (!location || typeof location !== 'string') {
  return "দুঃখিত, সঠিক location পাওয়া যায়নি।";
}

const apiKey = "YOUR_OPENWEATHERMAP_API_KEY";

const geoUrl = `https://api.openweathermap.org/geo/1.0/direct?q=${encodeURIComponent(location)}&limit=1&appid=${apiKey}`;
const geoResponse = await this.helpers.httpRequest({
  method: 'GET',
  url: geoUrl,
  json: true
});

if (!geoResponse || geoResponse.length === 0) {
  return `Location "${location}" খুঁজে পাওয়া যায়নি।`;
}

const { lat, lon } = geoResponse[0];

const weatherUrl = `https://api.openweathermap.org/data/2.5/weather?lat=${lat}&lon=${lon}&appid=${apiKey}&units=metric`;
const weatherResponse = await this.helpers.httpRequest({
  method: 'GET',
  url: weatherUrl,
  json: true
});

return JSON.stringify({
  location: location,
  temperature: weatherResponse.main.temp,
  feels_like: weatherResponse.main.feels_like,
  description: weatherResponse.weather[0].description,
  humidity: weatherResponse.main.humidity,
  wind_speed: weatherResponse.wind.speed
});

